// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Run loop: sitemap seeds, robots, rate, fetch, retry, breaker
// Flo: resume claims > seed from sitemap > pick due URL whose host is ready > robots decision logged > fetch+validate+store > done/fail/DLQ > breaker check > summary
// I/O: seed URLs + Conf + open Db (caller) > Summ counts; rows in fron, page, reco, logz
// ===================================================================
const std = @import("std"); const urln = @import("ut-urlz-norm.zig"); const tmfx = @import("nt-fetc-time.zig"); const robo = @import("pa-robo-txtz.zig"); const smap = @import("pa-site-maps.zig"); const fron = @import("qu-fron-main.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const rate = @import("ru-rate-limi.zig"); const brea = @import("ru-brea-circ.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const ladd = @import("ru-tier-ladd.zig"); const trap = @import("pa-trap-dete.zig"); const site = @import("cf-site-rule.zig"); const file = @import("st-stor-file.zig"); const vbas = @import("nt-vend-base.zig"); const revi = @import("ru-revi-sche.zig");
const CF = .{ .agnt = "scra", .smax = 5000, .subz = 5, .nap = 200, .nmax = 2000, .batz = 16, .perm = @as([]const []const u8, &.{ "NotText", "TooBig", "BadUrl", "BlockedHost", "CharUnsupported", "RedirectLoop", "TooManyRedirects" }) };
pub const Summ = struct { seen: u32 = 0, done: u32 = 0, fail: u32 = 0, skip: u32 = 0, blok: u32 = 0, dead: i64 = 0, uniq: u32 = 0, halt: bool = false, incm: bool = false, trap: u32 = 0 };
pub const Walk = struct { gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, priv: bool, gapz: i64, base: i64 = 1000, back: ?vbas.Backend = null, go: bool = false, foll: u32 = 0, geoz: []const u8 = "", rate: rate.Rate, brek: brea.Brea = brea.Brea.init(20, 10, 50), parn: std.heap.ArenaAllocator, robs: std.StringHashMapUnmanaged(robo.Robo) = .empty,
pub fn init(gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, priv: bool) Walk { return .{ .gpaz = gpaz, .iozz = iozz, .conf = conf, .dbzz = dbzz, .dirz = dirz, .priv = priv, .gapz = @as(i64, conf.rate_host_seco) * 1000, .rate = rate.Rate.init(gpaz, @intCast(@abs(std.Io.Clock.real.now(iozz).toMilliseconds()))), .parn = std.heap.ArenaAllocator.init(gpaz) }; }
pub fn deinit(self: *Walk) void { self.rate.deinit(); self.parn.deinit(); }
fn nowMs(self: *Walk) i64 { return @intCast(std.Io.Clock.real.now(self.iozz).toMilliseconds()); }
fn nap(self: *Walk, mill: i64) void { std.Io.sleep(self.iozz, .fromMilliseconds(@min(@max(mill, 1), CF.nmax)), .awake) catch {}; }
fn origin(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { const part = try urln.urlSplit(urlz); return std.fmt.allocPrint(aren, "{s}://{s}{s}{s}", .{ part.sche, part.host, if (part.dflt) "" else ":", if (part.dflt) "" else try std.fmt.allocPrint(aren, "{d}", .{part.port}) }); }
pub fn walkSeed(self: *Walk, urls: []const []const u8) !u32 { var addz: u32 = 0; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); for (urls) |urlz| { const norm = urln.urlNorm(aren.allocator(), urlz) catch continue; const part = try urln.urlSplit(norm); if (try fron.fronAdd(self.dbzz, norm, part.host, self.nowMs())) addz += 1; } return addz; }
fn textGet(self: *Walk, aren: std.mem.Allocator, urlz: []const u8) !struct { code: u16, body: []const u8 } { var opts = try pipe.optsMake(aren, self.conf, self.priv); opts.body_maxz = @min(opts.body_maxz, 20 << 20); var resp = try tmfx.fetcTime(self.gpaz, self.iozz, urlz, opts, .{}); defer resp.free(self.gpaz); return .{ .code = resp.code, .body = try aren.dupe(u8, resp.body) }; }
pub fn walkSmap(self: *Walk, rooturl: []const u8) !u32 { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); const base = try origin(allo, rooturl); const rb = try self.roboGet(base); var todo: std.ArrayList([]const u8) = .empty; try todo.append(allo, try std.fmt.allocPrint(allo, "{s}/sitemap.xml", .{base})); for (rb.maps) |item| if (std.mem.startsWith(u8, item, "http")) try todo.append(allo, try allo.dupe(u8, item)); var addz: u32 = 0; var subs: usize = 0; var indx: usize = 0; while (indx < todo.items.len and subs < CF.subz + 1) : (indx += 1) { subs += 1; const got = self.textGet(allo, todo.items[indx]) catch continue; if (got.code != 200) continue; const res = try smap.smapParse(allo, got.body, CF.smax); if (res.indx) { for (res.urls) |item| if (todo.items.len < CF.subz + 2) try todo.append(allo, item); } else addz += try self.walkSeed(res.urls); } return addz; }
fn roboGet(self: *Walk, base: []const u8) !robo.Robo { if (self.robs.get(base)) |hit| return hit; const parn = self.parn.allocator(); var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const urlz = try std.fmt.allocPrint(aren.allocator(), "{s}/robots.txt", .{base}); var rob: robo.Robo = .{}; if (self.textGet(aren.allocator(), urlz)) |got| { rob.mode = robo.roboStat(got.code); if (rob.mode == .pars) rob = try robo.roboParse(parn, got.body, CF.agnt); } else |_| { rob.mode = .deny; } try self.robs.put(parn, try parn.dupe(u8, base), rob); return rob; }
fn fetchOne(self: *Walk, aren: std.mem.Allocator, urlz: []const u8) !pipe.Outc { if (self.back) |bck| { var lad: ladd.Ladd = .{ .gpaz = self.gpaz, .iozz = self.iozz, .conf = self.conf, .dbzz = self.dbzz, .dirz = self.dirz, .back = bck, .go = self.go, .geoz = self.geoz, .priv = self.priv }; return ladd.laddFetc(&lad, aren, urlz); } return pipe.pageFetc(self.gpaz, aren, self.iozz, self.conf, self.dbzz, self.dirz, urlz, self.priv); }
pub fn walkRevi(self: *Walk, limz: i64) !u32 { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const now = self.nowMs(); const due = try revi.reviDue(self.dbzz, aren.allocator(), now, limz); var cnt: u32 = 0; for (due) |urlz| { const part = urln.urlSplit(urlz) catch continue; try revi.reviQueu(self.dbzz, urlz, part.host, now); cnt += 1; } return cnt; }
fn codeFind(list: []const u32, code: u16) bool { for (list) |item| { if (item == code) return true; } return false; }
fn globAny(list: []const []const u8, path: []const u8) bool { for (list) |patn| { if (site.globMach(patn, path)) return true; } return false; }
fn follow(self: *Walk, sum: *Summ, aren: std.mem.Allocator, item: fron.Item, outc: pipe.Outc, mcfg: cfgz.Conf) !void { var took: u32 = 0; if (self.foll == 0 or outc.hexz.len != 64) return; if (!std.mem.eql(u8, outc.kind, "text") and !std.mem.eql(u8, outc.kind, "ldjs") and !std.mem.eql(u8, outc.kind, "next")) return; const rawd = try std.fs.path.join(aren, &.{ self.dirz, "raw" }); const html = file.fileLoad(aren, self.iozz, rawd, outc.hexz[0..64].*, 20 << 20) catch return; const links = try trap.linkFind(aren, item.urlz, html); const now = self.nowMs(); for (links) |lk| { if (self.foll == 0) break; if (lk.trap) { sum.trap += 1; try inde.logzAdd(self.dbzz, .{ .urlz = lk.urlz, .code = 0, .tier = 1, .vend = "", .cred = 0, .micr = 0, .robo = "none", .timz = now, .note = try std.fmt.allocPrint(aren, "trap link skipped: {s}", .{lk.why}) }); continue; } const norm = urln.urlNorm(aren, lk.urlz) catch continue; const part = urln.urlSplit(norm) catch continue; if (mcfg.foll_incl_list.len > 0 and !globAny(mcfg.foll_incl_list, part.path)) continue; if (globAny(mcfg.foll_excl_list, part.path)) continue; if (mcfg.foll_maxz > 0 and took >= mcfg.foll_maxz) break; if (try fron.fronAdd(self.dbzz, norm, part.host, now)) { self.foll -= 1; took += 1; } } }
fn permOk(name: []const u8) bool { for (CF.perm) |item| if (std.mem.eql(u8, item, name)) return true; return false; }
fn failOne(self: *Walk, sum: *Summ, urlz: []const u8, errz: []const u8, now: i64, perm: bool, push: bool, maxz: i64, base: i64) !void { _ = try fron.fronFail(self.dbzz, urlz, errz, now, if (perm) 1 else maxz, base); sum.fail += 1; if (push) self.brek.push(false); }
fn one(self: *Walk, sum: *Summ, item: fron.Item, aren: std.mem.Allocator) !void { try fron.fronLock(self.dbzz, item.urlz); sum.seen += 1; const part = try urln.urlSplit(item.urlz); const mcfg = site.siteConf(aren, self.conf, item.host, part.path) catch self.conf; const rmax: i64 = mcfg.retr_cont_maxz; const rbas: i64 = if (mcfg.retr_back_seco > 0) @as(i64, mcfg.retr_back_seco) * 1000 else self.base; const base = try origin(aren, item.urlz); const rb = try self.roboGet(base); const pq = if (part.quer.len > 0) try std.fmt.allocPrint(aren, "{s}?{s}", .{ part.path, part.quer }) else part.path; const dec = robo.roboAllow(rb, pq); var now = self.nowMs(); try inde.logzAdd(self.dbzz, .{ .urlz = item.urlz, .code = 0, .tier = 1, .vend = "", .cred = 0, .micr = 0, .robo = try std.fmt.allocPrint(aren, "{s}: {s}", .{ if (dec.okay) "allow" else "deny", dec.rule }), .timz = now, .note = "robots decision" });
if (!dec.okay) { try fron.fronDone(self.dbzz, item.urlz); sum.skip += 1; return; }
const gapb: i64 = if (mcfg.rate_host_seco != self.conf.rate_host_seco) @as(i64, mcfg.rate_host_seco) * 1000 else self.gapz; var gap = @max(gapb, @as(i64, rb.delz)); if (mcfg.rate_jitt_pctz > 0 and gap > 0) { var rbuf: [2]u8 = undefined; self.iozz.random(&rbuf); const rval: i64 = @as(i64, rbuf[0]) | (@as(i64, rbuf[1]) << 8); gap += @divFloor(gap * @as(i64, mcfg.rate_jitt_pctz) * rval, 6553500); } const outc = self.fetchOne(aren, item.urlz) catch |err| { now = self.nowMs(); try self.rate.mark(item.host, now, gap); if (err == error.OverCap or err == error.KillOn) { self.brek.trip = true; } try self.failOne(sum, item.urlz, @errorName(err), now, permOk(@errorName(err)), !permOk(@errorName(err)), rmax, rbas); return; }; now = self.nowMs(); try self.rate.mark(item.host, now, gap);
if (std.mem.eql(u8, outc.stat, "new") or std.mem.eql(u8, outc.stat, "same") or std.mem.eql(u8, outc.stat, "notm")) { try fron.fronDone(self.dbzz, item.urlz); sum.done += 1; sum.uniq += 1; self.brek.push(true); try follow(self, sum, aren, item, outc, mcfg); return; }
if (std.mem.eql(u8, outc.stat, "http")) { if (outc.code == 404 or outc.code == 410) { try fron.fronDone(self.dbzz, item.urlz); sum.done += 1; return; } if ((outc.code == 429 or outc.code == 503) and mcfg.retr_afte_enab) try self.rate.hold(item.host, now, @divFloor(@as(i64, outc.retr) * 1000 * @as(i64, mcfg.rate_429z_pctz), 100)); if (outc.code == 401 or outc.code == 403) sum.blok += 1; const nort = mcfg.retr_code_list.len > 0 and !codeFind(mcfg.retr_code_list, outc.code); try self.failOne(sum, item.urlz, try std.fmt.allocPrint(aren, "http {d}", .{outc.code}), now, nort, !nort, rmax, rbas); return; }
sum.blok += 1; try self.failOne(sum, item.urlz, outc.stat, now, false, true, rmax, rbas); }
pub fn walkRun(self: *Walk, declz: ?u32) !Summ { var sum: Summ = .{}; _ = try fron.fronResume(self.dbzz); while (!self.brek.trip) { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); var now = self.nowMs(); const due = try fron.fronDue(self.dbzz, aren.allocator(), now, CF.batz); if (due.len == 0) { const soon = try fron.fronSoon(self.dbzz) orelse break; self.nap(soon - now); continue; } var pick: ?fron.Item = null; var minw: i64 = CF.nmax; for (due) |item| { const wait = self.rate.wait(item.host, now); if (wait == 0) { pick = item; break; } minw = @min(minw, wait); } if (pick) |item| { try self.one(&sum, item, aren.allocator()); } else { self.nap(minw); now = self.nowMs(); } } sum.halt = self.brek.trip; sum.dead = try fron.fronCont(self.dbzz, 2); if (declz) |decl| sum.incm = sum.uniq < decl; return sum; } };
